describe('Tablet Layout - Two-Column Grid', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.viewport('ipad-2', 'portrait');
  });

  it('should display two-column grid layout on tablet viewport', () => {
    cy.get('[data-testid="grid-container"]').should('exist');
    cy.get('[data-testid="grid-container"]').should('have.css', 'display', 'grid');
    cy.get('[data-testid="grid-container"]').should('have.css', 'grid-template-columns', '1fr 1fr');
    cy.get('[data-testid="grid-item"]').should('have.length.greaterThan', 1);
    cy.get('[data-testid="grid-item"]').each(($item) => {
      cy.wrap($item).should('be.visible');
    });
  });

  it('should maintain two-column layout when resizing within tablet range', () => {
    cy.viewport('ipad-2', 'landscape');
    cy.get('[data-testid="grid-container"]').should('have.css', 'grid-template-columns', '1fr 1fr');
    cy.get('[data-testid="grid-item"]').first().should('be.visible');
  });

  it('should switch from single column to two columns when transitioning from mobile to tablet', () => {
    cy.viewport('iphone-x', 'portrait');
    cy.get('[data-testid="grid-container"]').should('have.css', 'grid-template-columns', '1fr');
    cy.viewport('ipad-2', 'portrait');
    cy.get('[data-testid="grid-container"]').should('have.css', 'grid-template-columns', '1fr 1fr');
  });

  it('should properly space grid items in two-column layout', () => {
    cy.get('[data-testid="grid-container"]').should('have.css', 'gap');
    cy.get('[data-testid="grid-item"]').first().then(($firstItem) => {
      const firstItemWidth = $firstItem.width();
      cy.get('[data-testid="grid-item"]').eq(1).then(($secondItem) => {
        const secondItemWidth = $secondItem.width();
        expect(firstItemWidth).to.be.closeTo(secondItemWidth, 5);
      });
    });
  });

  it('should handle edge case with odd number of grid items in two-column layout', () => {
    cy.get('[data-testid="grid-item"]').then(($items) => {
      const itemCount = $items.length;
      cy.get('[data-testid="grid-container"]').should('have.css', 'grid-template-columns', '1fr 1fr');
      if (itemCount % 2 !== 0) {
        cy.get('[data-testid="grid-item"]').last().should('be.visible');
        cy.get('[data-testid="grid-item"]').last().should('have.css', 'grid-column');
      }
    });
  });

  it('should not display horizontal scrollbar in two-column tablet layout', () => {
    cy.get('body').should('not.have.css', 'overflow-x', 'scroll');
    cy.window().then((win) => {
      expect(win.innerWidth).to.be.greaterThan(0);
      expect(win.document.documentElement.scrollWidth).to.be.lessThanOrEqual(win.innerWidth + 1);
    });
  });
});
